# Generated by AgentFoundry Agent Foundry — safe to edit.
# AgentFoundry Sidecar loader. Reads skills + guardrails from the locally-running
# sidecar (http://127.0.0.1:8721/state) and composes them into a system-
# prompt prefix. See https://wiki.codenow.pro/concepts/deployment-modes
#
# Fails open: if the sidecar isn't running, returns "" and the agent runs
# with whatever you'd otherwise compose.

import json
import os
import urllib.request
import urllib.error
from typing import Any, Dict, List


def load_sidecar_system_prompt(timeout: float = 1.5) -> str:
    port = os.environ.get("CODENOW_SIDECAR_PORT", "8721")
    host = os.environ.get("CODENOW_SIDECAR_HOST", "127.0.0.1")
    url = f"http://{host}:{port}/state"
    try:
        req = urllib.request.Request(url, headers={"accept": "application/json"})
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            if resp.status != 200:
                return ""
            payload: Dict[str, Any] = json.loads(resp.read().decode("utf-8"))
    except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError, json.JSONDecodeError):
        return ""

    skills: List[Dict[str, Any]] = payload.get("skills") or []
    guardrails: List[Dict[str, Any]] = payload.get("guardrails") or []
    if not skills and not guardrails:
        return ""

    parts: List[str] = []
    if skills:
        parts.append("## Skills")
        for s in skills:
            parts.append(f"### {s.get('title','(untitled)')}\n{s.get('body','')}")
    if guardrails:
        parts.append("## Guardrails")
        for g in guardrails:
            floor = g.get("trustscore_floor")
            floor_line = f"\nMinimum TrustScore: {floor}" if isinstance(floor, (int, float)) else ""
            parts.append(
                f"### {g.get('agent_slug','(unknown agent)')}\n"
                f"{json.dumps(g.get('policy') or {}, indent=2)}"
                f"{floor_line}"
            )
    return "\n\n".join(parts)


def post_run_to_sidecar(run: Dict[str, Any], timeout: float = 2.0) -> None:
    """Best-effort: hand a recorded run to the sidecar so it forwards to AgentFoundry.

    Call this from your agent's run-end hook. If the sidecar isn't running
    the run still lives in .codenow/runs/<slug>/ on disk and gets picked up
    the next time AgentFoundry imports the project."""
    port = os.environ.get("CODENOW_SIDECAR_PORT", "8721")
    host = os.environ.get("CODENOW_SIDECAR_HOST", "127.0.0.1")
    url = f"http://{host}:{port}/runs"
    try:
        data = json.dumps(run).encode("utf-8")
        req = urllib.request.Request(url, data=data, method="POST",
                                     headers={"content-type": "application/json"})
        urllib.request.urlopen(req, timeout=timeout).close()
    except Exception:
        pass
